import { View } from 'react-native';
import type { DiscomfortAssessment } from '@forma/shared';
import { Banner } from '@/components/ui/Feedback';
import { Text } from '@/components/ui/Text';

/** Deterministic safety guidance from the shared triage engine — never generated by AI. */
export function SafetyCard({ assessment }: { assessment: DiscomfortAssessment }) {
  const tone = assessment.level === 'urgent' ? 'danger' : assessment.level === 'ok' ? 'success' : assessment.level === 'modify' ? 'info' : 'warning';
  return (
    <Banner tone={tone} title={assessment.headline}>
      <View style={{ gap: 6 }}>
        {assessment.reasons.length ? <Text variant="caption" tone="muted">Because: {assessment.reasons.join('; ')}.</Text> : null}
        {assessment.guidance.map((g) => (
          <Text key={g} variant="caption">• {g}</Text>
        ))}
      </View>
    </Banner>
  );
}
